<script setup lang="ts">
import {apiError} from '~/composables/useApi'
type Version={id:string;version:number;target_version:number;credential_version:number;identity_hash:string;sha256:string;byte_size:number;observed_at:string;created_at:string}
type Diff={added:number;removed:number;unchanged_prefix:number;unchanged_suffix:number;exact:boolean;lines:{op:'add'|'remove'|'context';old_line:number|null;new_line:number|null;text:string}[]}
const props=defineProps<{targetId:string;profileConfigured:boolean;canBackup:boolean}>(),emit=defineEmits<{plans:[]}>(),api=useApi()
const known=ref<Version[]>([])
const path=`/connectors/targets/${props.targetId}/configuration-backups`,rows=ref<Version[]>([]),offset=ref(0),from=ref(''),to=ref(''),diff=ref<Diff|null>(null),loading=ref(false),error=ref(''),page=ref(0)
let disposed=false
async function load(next=0){loading.value=true;error.value='';diff.value=null;page.value=0;try{const r=await api.get<{data:Version[]}>(`${path}?limit=50&offset=${next}`);if(!disposed){rows.value=r.data;offset.value=next;known.value=Array.from(new Map([...known.value,...r.data].map(v=>[v.id,v])).values()).sort((a,b)=>b.version-a.version);if(next===0){to.value=r.data[0]?.id||'';from.value=r.data[1]?.id||''}}}catch(e){if(!disposed)error.value=apiError(e).message}finally{if(!disposed)loading.value=false}}
async function compare(){loading.value=true;error.value='';diff.value=null;page.value=0;try{const r=await api.get<{data:{diff:Diff}}>(`${path}/${to.value}/diff?from=${encodeURIComponent(from.value)}`);if(!disposed)diff.value=r.data.diff}catch(e){if(!disposed)error.value=apiError(e).message}finally{if(!disposed)loading.value=false}}
const visible=computed(()=>diff.value?.lines.slice(page.value*100,(page.value+1)*100)||[])
const base=useRuntimeConfig().public.apiBase||'/api/v1'
async function download(row:Version){loading.value=true;error.value='';try{const response=await fetch(`${base}${path}/${row.id}/export`,{credentials:'include',cache:'no-store',redirect:'error'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const blob=await response.blob();if(blob.size!==row.byte_size)throw new Error('Неверный размер файла');const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join('');if(digest!==row.sha256)throw new Error('Ошибка SHA-256');if(disposed)return;const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`routeros-v${row.version}.rsc`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(!disposed)error.value=e instanceof Error?e.message:apiError(e).message}finally{if(!disposed)loading.value=false}}
watch([from,to],()=>{diff.value=null;page.value=0})
onMounted(()=>void load());onBeforeUnmount(()=>{disposed=true})
</script>
<template><section class="panel" data-testid="network-configuration-backup"><h2>Резервные копии конфигурации RouterOS</h2><p class="muted">Нативный экспорт .rsc без show-sensitive. Новая версия создаётся при изменении конфигурации или ревизии подключения. Экспорт не включает пароли, ключи и сертификаты; файл может содержать другие чувствительные сведения.</p>
<p v-if="!profileConfigured" role="alert">Для нового сбора настройте TLS и identity профиль.</p><button v-if="canBackup&&profileConfigured" class="btn primary" :disabled="loading" @click="emit('plans')">Создать план / запустить backup</button> <button class="btn" :disabled="loading" @click="load()">Обновить версии</button><p v-if="canBackup" class="muted">В планах выберите routeros.configuration-backup, Inspect и задайте расписание. Для ручного запуска используйте «Запустить» у плана.</p>
<p v-if="error" role="alert">{{error}}</p><p v-if="loading" role="status">Загрузка…</p><p v-if="!rows.length&&!loading">Нет резервных копий.</p>
<div class="table-wrap"><table class="table"><thead><tr><th>Версия</th><th>Собрано</th><th>Размер / SHA-256</th><th>Экспорт</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>v{{r.version}}</td><td>{{r.observed_at}}</td><td>{{r.byte_size}} B <small style="overflow-wrap:anywhere">{{r.sha256}}</small></td><td><button class="btn" :disabled="loading" @click="download(r)">Скачать .rsc</button></td></tr></tbody></table></div>
<button class="btn" :disabled="loading||offset===0" @click="load(offset-50)">Назад</button> <button class="btn" :disabled="loading||rows.length&lt;50||offset>=10000" @click="load(offset+50)">Ранее</button>
<form v-if="known.length>1" class="form-row" @submit.prevent="compare"><label>Старая версия<select v-model="from" :disabled="loading"><option v-for="r in known" :key="r.id" :value="r.id">v{{r.version}}</option></select></label><label>Новая версия<select v-model="to" :disabled="loading"><option v-for="r in known" :key="r.id" :value="r.id">v{{r.version}}</option></select></label><button class="btn" :disabled="loading||!from||!to||from===to">Сравнить</button></form>
<template v-if="diff"><h3>Различия: +{{diff.added}} / −{{diff.removed}}</h3><p v-if="!diff.exact">Большой набор изменений: показан блок замены целиком.</p><p v-if="!diff.lines.length">Изменений нет.</p><div class="table-wrap"><table class="table"><thead><tr><th>Было</th><th>Стало</th><th>Строка</th></tr></thead><tbody><tr v-for="(line,i) in visible" :key="i"><td>{{line.old_line??'—'}}</td><td>{{line.new_line??'—'}}</td><td style="white-space:pre-wrap;overflow-wrap:anywhere" :class="line.op==='add'?'diff-add':line.op==='remove'?'diff-remove':''">{{line.op==='add'?'+ ':line.op==='remove'?'− ':'  '}}{{line.text}}</td></tr></tbody></table></div><button class="btn" :disabled="page===0" @click="page--">Назад</button> <button class="btn" :disabled="(page+1)*100>=diff.lines.length" @click="page++">Далее</button></template></section></template>
<style scoped>.diff-add{color:#169a54}.diff-remove{color:#d34b4b}</style>
